package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Report struct {
	ID    int    `json:"id"`
	Title string `json:"title"`
	Owner string `json:"owner"`
}

// getReports handles report listing with dynamic filtering
func getReports(w http.ResponseWriter, r *http.Request) {
	// Auth check - verify session token exists
	sessionToken := r.Header.Get("X-Session-Token")
	if sessionToken == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	// Validate session (simplified - checks format only)
	if len(sessionToken) != 64 {
		http.Error(w, "invalid session", http.StatusForbidden)
		return
	}

	owner := r.URL.Query().Get("owner")
	status := r.URL.Query().Get("status")
	groupBy := r.URL.Query().Get("group")

	// Build base query with parameterized WHERE clauses
	query := "SELECT id, title, owner FROM reports WHERE 1=1"
	args := []interface{}{}
	argIdx := 1

	if owner != "" {
		query += fmt.Sprintf(" AND owner = $%d", argIdx)
		args = append(args, owner)
		argIdx++
	}

	if status != "" {
		query += fmt.Sprintf(" AND status = $%d", argIdx)
		args = append(args, status)
		argIdx++
	}

	// Group by clause - developer assumed limited values
	if groupBy != "" {
		// NOTE: attempted sanitization by removing dangerous keywords
		filtered := strings.ReplaceAll(groupBy, ";", "")
		filtered = strings.ReplaceAll(filtered, "--", "")
		query += " GROUP BY " + filtered
	}

	query += " LIMIT 100"

	rows, err := db.Query(query, args...)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var reports []Report
	for rows.Next() {
		var rpt Report
		if err := rows.Scan(&rpt.ID, &rpt.Title, &rpt.Owner); err != nil {
			continue
		}
		reports = append(reports, rpt)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(reports)
}

// healthCheck for load balancer probes
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/reports", getReports)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
